        assert task.completed_at is None
        assert task.tags == []
        assert task.created_at.tzinfo is not None

    @pytest.mark.parametrize(
        "due_at, status, expected",
        [
            (None, TaskStatus.PENDING, False),
            (datetime(2025, 1, 1, tzinfo=timezone.utc), TaskStatus.DONE, False),
            (datetime(2025, 1, 1, tzinfo=timezone.utc), TaskStatus.PENDING, True),
            (datetime(2099, 1, 1, tzinfo=timezone.utc), TaskStatus.PENDING, False),
        ],
        ids=["no-due-date", "done-ignored", "past-due-pending", "future-due"],
    )
    def test_is_overdue(self, due_at, status, expected):
        now = datetime(2025, 6, 15, tzinfo=timezone.utc)
        task = Task(id=1, title="t", status=status, due_at=due_at)
        assert task.is_overdue(now) is expected

"""Tests for tasks_api.queries — TaskQuery, apply_query, TaskPage."""

from __future__ import annotations

from datetime import datetime, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query

NOW = datetime(2025, 6, 15, 12, 0, 0, tzinfo=timezone.utc)


def _make_task(id, title="t", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
               due_at=None, tags=None, created_at=None):
    return Task(
        id=id, title=title, status=status, priority=priority,
        due_at=due_at, tags=tags or [],
        created_at=created_at or datetime(2025, 1, id, tzinfo=timezone.utc),
    )


# ── TaskQuery validation ─────────────────────────────────────────────────────

class TestTaskQueryValidation:
    def test_defaults(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.limit == 20
        assert q.offset == 0
        assert q.descending is False

    def test_invalid_sort_field_raises(self):
        with pytest.raises(TaskQueryError, match="sort must be one of"):
            TaskQuery(sort="invalid")

    @pytest.mark.parametrize("limit", [0, -1, 101, "abc"])
    def test_invalid_limit_raises(self, limit):
        with pytest.raises(TaskQueryError, match="limit must be"):
            TaskQuery(limit=limit)

    def test_negative_offset_raises(self):
        with pytest.raises(TaskQueryError, match="offset must be"):
            TaskQuery(offset=-1)

    def test_tag_is_normalized(self):
        q = TaskQuery(tag=" Python ")
        assert q.tag == "python"

    def test_invalid_tag_raises(self):
        with pytest.raises(ValueError):
            TaskQuery(tag="has space")

    def test_search_whitespace_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None

    def test_search_stripped(self):
        q = TaskQuery(search="  hello  ")
        assert q.search == "hello"


# ── TaskPage ─────────────────────────────────────────────────────────────────

class TestTaskPage:
    def test_has_more_true(self):
        page = TaskPage(items=[_make_task(1)], total=5, limit=2, offset=0)
        assert page.has_more is True

    def test_has_more_false_at_end(self):
        page = TaskPage(items=[_make_task(1)], total=1, limit=20, offset=0)
        assert page.has_more is False

    def test_has_more_false_exact(self):
        tasks = [_make_task(1), _make_task(2)]
        page = TaskPage(items=tasks, total=2, limit=2, offset=0)
        assert page.has_more is False


# ── apply_query filtering ────────────────────────────────────────────────────

class TestApplyQueryFiltering:
    @pytest.fixture
    def tasks(self):
        return [
            _make_task(1, "Buy milk", status=TaskStatus.PENDING,
                       tags=[Tag("shopping")],
                       due_at=datetime(2025, 1, 1, tzinfo=timezone.utc)),
            _make_task(2, "Write code", status=TaskStatus.DONE,
                       tags=[Tag("work")]),
            _make_task(3, "Buy eggs", status=TaskStatus.PENDING,
                       tags=[Tag("shopping"), Tag("food")]),
        ]

    def test_no_filter_returns_all(self, tasks):
        page = apply_query(tasks, TaskQuery(), NOW)
        assert page.total == 3

    def test_filter_by_status(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.DONE), NOW)
        assert page.total == 1
        assert page.items[0].id == 2

    def test_filter_by_tag(self, tasks):
        page = apply_query(tasks, TaskQuery(tag="shopping"), NOW)
        assert page.total == 2

    def test_filter_by_search(self, tasks):
        page = apply_query(tasks, TaskQuery(search="buy"), NOW)
        assert page.total == 2
        assert all("buy" in t.title.lower() for t in page.items)

    def test_filter_overdue_true(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=True), NOW)
        assert page.total == 1
        assert page.items[0].id == 1

    def test_filter_overdue_false(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=False), NOW)
        assert page.total == 2
        ids = {t.id for t in page.items}
        assert ids == {2, 3}

    def test_combined_filters(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING, search="egg"), NOW)
        assert page.total == 1
        assert page.items[0].id == 3


# ── apply_query sorting ──────────────────────────────────────────────────────

class TestApplyQuerySorting:
    @pytest.fixture
    def tasks(self):
        return [
            _make_task(1, "Charlie", priority=TaskPriority.LOW,
                       created_at=datetime(2025, 3, 1, tzinfo=timezone.utc),
                       due_at=datetime(2025, 7, 1, tzinfo=timezone.utc)),
            _make_task(2, "Alice", priority=TaskPriority.HIGH,
                       created_at=datetime(2025, 1, 1, tzinfo=timezone.utc)),
            _make_task(3, "Bob", priority=TaskPriority.MEDIUM,
                       created_at=datetime(2025, 2, 1, tzinfo=timezone.utc),
                       due_at=datetime(2025, 8, 1, tzinfo=timezone.utc)),
        ]

    def test_sort_by_created_at_asc(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="created_at"), NOW)
        assert [t.id for t in page.items] == [2, 3, 1]

    def test_sort_by_created_at_desc(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="created_at", descending=True), NOW)
        assert [t.id for t in page.items] == [1, 3, 2]

    def test_sort_by_title(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="title"), NOW)
        assert [t.title for t in page.items] == ["Alice", "Bob", "Charlie"]

    def test_sort_by_priority(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="priority"), NOW)
        assert [t.priority for t in page.items] == [
            TaskPriority.HIGH, TaskPriority.MEDIUM, TaskPriority.LOW
        ]

    def test_sort_by_due_at_none_last(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="due_at"), NOW)
        assert page.items[0].due_at is not None
        assert page.items[-1].due_at is None


# ── apply_query pagination ───────────────────────────────────────────────────

class TestApplyQueryPagination:
    @pytest.fixture
    def tasks(self):
        return [_make_task(i, f"task-{i}") for i in range(1, 11)]

    def test_limit(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=3), NOW)
        assert len(page.items) == 3
        assert page.total == 10
        assert page.has_more is True

    def test_offset(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=5, offset=8), NOW)
        assert len(page.items) == 2
        assert page.has_more is False

    def test_offset_beyond_total(self, tasks):
        page = apply_query(tasks, TaskQuery(offset=100), NOW)
        assert len(page.items) == 0
        assert page.total == 10
        assert page.has_more is False

"""Tests for tasks_api.repository — InMemoryTaskRepository and normalize_tags."""

from __future__ import annotations

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags


class TestInMemoryTaskRepository:
    @pytest.fixture
    def repo(self):
        return InMemoryTaskRepository()

    def _make_task(self, id=1, title="test"):
        return Task(id=id, title=title)

    def test_add_and_get(self, repo):
        task = self._make_task()
        repo.add(task)
        assert repo.get(1) is task

    def test_get_missing_returns_none(self, repo):
        assert repo.get(999) is None

    def test_add_duplicate_raises(self, repo):
        repo.add(self._make_task())
        with pytest.raises(ValueError, match="already exists"):
            repo.add(self._make_task())

    def test_list_returns_snapshot(self, repo):
        repo.add(self._make_task(1))
        repo.add(self._make_task(2))
        result = list(repo.list())
        assert len(result) == 2

    def test_update_existing(self, repo):
        task = self._make_task()
        repo.add(task)
        task.title = "updated"
        repo.update(task)
        assert repo.get(1).title == "updated"

    def test_update_missing_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(self._make_task(99))

    def test_delete_existing(self, repo):
        repo.add(self._make_task())
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing_returns_false(self, repo):
        assert repo.delete(999) is False

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2
        assert repo.next_id() == 3


class TestNormalizeTags:
    def test_deduplicates(self):
        result = normalize_tags([Tag("python"), Tag("Python"), Tag("PYTHON")])
        assert len(result) == 1
        assert result[0].name == "python"

    def test_string_conversion(self):
        result = normalize_tags(["Flask", "  django  "])
        assert [t.name for t in result] == ["flask", "django"]

    def test_preserves_order(self):
        result = normalize_tags(["b", "a", "c"])
        assert [t.name for t in result] == ["b", "a", "c"]

    def test_empty_iterable(self):
        assert normalize_tags([]) == []

    def test_mixed_tag_and_string(self):
        result = normalize_tags([Tag("alpha"), "beta"])
        assert len(result) == 2

